#[napi]
pub struct JsLiterLlmErrorInfo {
    pub code: u32,
    pub status_code: u16,
    pub retry_after: Option<i64>,
    pub is_transient: bool,
    pub error_type: String,
}

/// Resolve the stable numeric error code for a `liter_llm::LiterLlmError` variant.
#[allow(dead_code)]
fn liter_llm_error_error_code(e: &liter_llm::LiterLlmError) -> u32 {
    #[allow(unreachable_patterns)]
    match e {
        liter_llm::LiterLlmError::Authentication { .. } => 100,
        liter_llm::LiterLlmError::RateLimited { .. } => 101,
        liter_llm::LiterLlmError::BadRequest { .. } => 102,
        liter_llm::LiterLlmError::ContextWindowExceeded { .. } => 103,
        liter_llm::LiterLlmError::ContentPolicy { .. } => 104,
        liter_llm::LiterLlmError::NotFound { .. } => 105,
        liter_llm::LiterLlmError::ServerError { .. } => 106,
        liter_llm::LiterLlmError::ServiceUnavailable { .. } => 107,
        liter_llm::LiterLlmError::Timeout => 108,
        liter_llm::LiterLlmError::Network { .. } => 109,
        liter_llm::LiterLlmError::Streaming { .. } => 110,
        liter_llm::LiterLlmError::EndpointNotSupported { .. } => 111,
        liter_llm::LiterLlmError::InvalidHeader { .. } => 112,
        liter_llm::LiterLlmError::Serialization(..) => 113,
        liter_llm::LiterLlmError::BudgetExceeded { .. } => 114,
        liter_llm::LiterLlmError::HookRejected { .. } => 115,
        liter_llm::LiterLlmError::InternalError { .. } => 116,
        liter_llm::LiterLlmError::OutboundForbidden { .. } => 117,
        liter_llm::LiterLlmError::IdempotencyConflict { .. } => 118,
        liter_llm::LiterLlmError::IdempotencyInFlight { .. } => 119,
        liter_llm::LiterLlmError::ProviderQuotaExceeded { .. } => 120,
        _ => 2,
    }
}

#[allow(dead_code)]
fn liter_llm_error_info(e: &liter_llm::LiterLlmError) -> JsLiterLlmErrorInfo {
    JsLiterLlmErrorInfo {
        code: liter_llm_error_error_code(e),
        status_code: e.status_code(),
        retry_after: e.retry_after().map(|d| d.as_millis() as i64),
        is_transient: e.is_transient(),
        error_type: e.error_type().to_string(),
    }
}

#[napi]
impl JsLiterLlmErrorInfo {
    /// Stable numeric error code identifying the specific error variant.
    #[napi(js_name = "code")]
    pub fn code(&self) -> u32 {
        self.code
    }

    /// HTTP status code for this error (0 means no associated status).
    #[napi(js_name = "statusCode")]
    pub fn status_code(&self) -> u16 {
        self.status_code
    }

    /// `retry_after` in whole milliseconds (null when absent).
    #[napi(js_name = "retryAfter")]
    pub fn retry_after(&self) -> Option<i64> {
        self.retry_after
    }

    /// Returns `true` if the error is transient and a retry may succeed.
    #[napi(js_name = "isTransient")]
    pub fn is_transient(&self) -> bool {
        self.is_transient
    }

    /// Machine-readable error category string for matching and logging.
    #[napi(js_name = "errorType")]
    pub fn error_type(&self) -> String {
        self.error_type.clone()
    }
}
